async function test() {
  const rpc = "https://sepolia-rollup.arbitrum.io/rpc";
  // WETH on Arbitrum Sepolia: let us check 0x980B62Da83eFf3D4576C647993b0c1D7faf17c73 or others
  // Let us check popular addresses:
  // Usually wrapped ether has symbol() -> 0x95d89b41
  const candidates = [
    "0x980B62Da83eFf3D4576C647993b0c1D7faf17c73",
    "0x980b62da83eff3d4576c647993b0c1d7faf17c73",
    "0xb16F35c0Ae2912430DAc15764477E179D9B9EbEa"
  ];
  for (const addr of candidates) {
    const res = await fetch(rpc, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        jsonrpc: "2.0",
        id: 1,
        method: "eth_call",
        params: [{ to: addr, data: "0x95d89b41" }, "latest"]
      })
    }).then(r => r.json());
    console.log(addr, res);
  }
}
test();
'

